<div id="app-content"><div class="erp-page erp-mobile-page"><h1>Monteur</h1><p class="erp-sub">Zeit, Rapport, Fotos und Projektzugriff für unterwegs.</p><div class="erp-mobile-kpis"><div class="erp-card"><span>Heute erfasst</span><strong><?php p(number_format((float)$_['todayHours'],2,',','.'));?> h</strong></div><?php if($_['timer']):?><div class="erp-card erp-live-timer" data-start="<?php p($_['timer']['started_at']);?>" data-pause-seconds="<?php p((int)$_['timer']['pause_seconds']);?>" data-status="<?php p($_['timer']['status']);?>" data-paused-at="<?php p($_['timer']['paused_at']??'');?>"><span><?php p($_['timer']['project_no'].' · '.$_['timer']['title']);?></span><strong id="erp-live-duration">00:00:00</strong><small><?php p($_['timer']['activity']);?></small></div><?php endif;?></div><?php if($_['timer']):?><div class="erp-mobile-actions"><?php if($_['timer']['status']==='running'):?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.pauseTimer',['id'=>$_['timer']['id']]));?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><input type="hidden" name="returnTo" value="mobile"><button class="button">Pause</button></form><?php else:?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.resumeTimer',['id'=>$_['timer']['id']]));?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><input type="hidden" name="returnTo" value="mobile"><button class="button primary">Weiter</button></form><?php endif;?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.stopTimer',['id'=>$_['timer']['id']]));?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><input type="hidden" name="returnTo" value="mobile"><button class="button primary">Stoppen & buchen</button></form></div><?php else:?><form class="erp-form-card" method="post" action="<?php p($url->linkToRoute('reinhardterp.module.startTimer'));?>"><input type="hidden" na